    /**
     * 주문 입찰 생성 입력값을 검증합니다.
     */
    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new OrderBidAccessDeniedException("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new ProductSizeNotFoundException("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }

    /**
     * OrderBid 생성 및 저장을 수행합니다.
     */
    private OrderBid createAndSaveOrderBid(User user, ProductSize productSize, int bidPrice, Order order) {
        OrderBid orderBid = OrderBid.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .order(order)
                .build();

        // 양방향 관계 설정
        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }

    /**
     * 즉시 구매 주문 입찰을 생성합니다.
     *
     * @param buyerEmail 구매자 이메일
     * @param saleBidId 판매 입찰 ID
     * @param addressId 배송지 ID
        try {
            // 입력값 검증
            if (user == null) {
                throw new InvalidOrderDataException("사용자 정보가 없습니다.");
            }
            if (productSize == null) {
                throw new ProductSizeNotFoundException("상품 사이즈 정보가 없습니다.");
            }
            if (bidPrice <= 0) {
                throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
            }

            // 1. OrderItem 생성
            OrderItem orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);

            // 2. Order 생성
            Order order = Order.builder()
                    .user(user)
                    .totalAmount(bidPrice) // 입찰가를 총 금액으로 설정
                    .discountAmount(0) // 초기값은 0
                    .usedPoints(0) // 초기값은 0
                    .status(OrderStatus.PENDING_PAYMENT) // 결제 대기 상태
                    .build();

            // 3. OrderItem과 연관 설정
            order.addOrderItem(orderItem);

            // 4. Order 저장
            return orderRepository.save(order);
        } catch (Exception e) {
            if (e instanceof OrderException) {
                throw e;
            }
            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new OrderCreationFailedException("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

